    77	// Build PROVIDERS from available sources (with 'all' option prepended)
    78	function buildProviders(availableSources) {
    79	  if (!availableSources || availableSources.length === 0) {
    80	    return FALLBACK_PROVIDERS;
    81	  }
    82	  
    83	  // Normalize sources: handle both string arrays and object arrays
    84	  const normalizedSources = availableSources.map(s => {
    85	    if (typeof s === 'string') {
    86	      // Source is a string (e.g., "ticketmaster", "kulturhuset")
    87	      return { key: s, label: formatProviderLabel(s) };
    88	    }
    89	    // Source is an object with key/label properties
    90	    return { key: s.key, label: s.label || formatProviderLabel(s.key) };
    91	  });
    92	  
    93	  // Prepend 'all' option
    94	  return [
    95	    { key: 'all', label: 'Alla arrangörer' },
    96	    ...normalizedSources,
    97	  ];
    98	}
